import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Configurar sonidos y voz","description":"","frontmatter":{"title":"Configurar sonidos y voz","docId":"user.plugins.audio","translationKey":"user.plugins.audio","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"e0e5014682213e36dda2e4c02293b8f960f3c107bdb1679327fb00b92e02604b","translationRevision":"d85ec297953340cd285fd756720fe1dc90487a872424a23d9e0b59ecadcaa13d","order":20},"headers":[],"relativePath":"es/user/plugins/audio.md","filePath":"es/user/plugins/audio.md","lastUpdated":1795727787000}`),a={name:`es/user/plugins/audio.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="set-up-sounds-and-speech" tabindex="-1">Configurar sonidos y voz <a class="header-anchor" href="#set-up-sounds-and-speech" aria-label="Permalink to “Configurar sonidos y voz”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Reproduce un sonido previsible antes de conectarlo a un LIVE concurrido. Necesitas un dispositivo de salida funcional y un archivo de audio compatible. <strong>Play a sound</strong> (<code>audio.play</code>) es una acción integrada; los proveedores de voz, como una integración SonicBoom instalada, requieren configurar su propio plugin y servicio.</p><h2 id="test-a-local-sound" tabindex="-1">Probar un sonido local <a class="header-anchor" href="#test-a-local-sound" aria-label="Permalink to “Probar un sonido local”">​</a></h2><ol><li>En <strong>Automations → Actions</strong>, crea <strong>Play a sound</strong> (<code>audio.play</code>). Selecciona un archivo existente mediante el selector de medios.</li><li>Establece el volumen en <code>0.2</code> para la primera comprobación. El intervalo admitido va de <code>0</code> a <code>1</code>; cero significa silencio.</li><li>Elige la política de solapamiento: <code>allow</code> permite reproducción simultánea, <code>restart</code> reinicia el sonido y <code>drop</code> ignora una nueva instancia mientras ya se reproduce.</li><li>Guarda y lee la configuración antes de pulsar <strong>Test</strong>. La prueba puede producir sonido audible.</li><li>Escucha en el dispositivo previsto. Tras comprobar la reproducción local, vincula la acción a un evento con <a href="./../automations/recipes.html">filtro y espera</a> conservadores.</li></ol><p>La acción conserva una referencia a la ruta del archivo. TikTools no copia el audio a su base de datos. Mantén el archivo en esa ubicación e inclúyelo por separado cuando traslades o respaldes la configuración.</p><h2 id="configure-optional-speech" tabindex="-1">Configurar voz opcional <a class="header-anchor" href="#configure-optional-speech" aria-label="Permalink to “Configurar voz opcional”">​</a></h2><p>Instala el plugin de voz confiable desde <a href="./">Plugins</a>. En sus controles de conexión y ajustes, verifica dirección del servicio, autenticación, proveedor, idioma y voz o perfil. Carga el catálogo antes de probar una frase breve sin datos sensibles. Investiga una voz ausente como posible problema de catálogo, propiedad o proveedor; no inventes su identificador.</p><p>En SonicBoom, la síntesis, la admisión a reproducción y la finalización audible son resultados distintos. Una respuesta en cola o iniciada no demuestra que alguien escuchara la frase. La voz clonada puede tardar más que la llegada de mensajes: revisa diagnósticos de cola y saturación y limita los eventos admitidos.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, estado y recuperación <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to “Resultado esperado, estado y recuperación”">​</a></h2><p>El audio local está disponible cuando el host anuncia su capacidad. La voz depende del plugin instalado y del servicio accesible; esta guía no garantiza aceptación de cada proveedor, dispositivo o plataforma. Si no suena, comprueba archivo, volumen, salida, pausa y error de ejecución. Para voz, verifica servicio y catálogo antes de repetir. Evita pruebas repetidas durante una emisión y consulta <a href="./../preferences/troubleshooting.html">diagnósticos</a> sin compartir tokens ni texto privado hablado.</p><h2 id="command-line-operations" tabindex="-1">Operaciones de línea de comandos <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operaciones de línea de comandos”">​</a></h2><p>Cada operación de esta guía también está disponible desde la CLI: sin conexión, scriptable y apta para agentes. Las líneas de uso son sintaxis del parser y permanecen en inglés en todos los idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools media validate &lt;path&gt; [--kind audio&amp;#124;video&amp;#124;image&amp;#124;other]</code></td><td>validar un archivo multimedia antes de usarlo en acciones</td></tr></tbody></table><p>Consulta la <a href="./../../developer/cli.html">referencia completa de comandos</a> para las convenciones, la salida JSON y los marcadores de operaciones destructivas.</p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};